// HasBenchRun applies the HasEdge predicate on the "bench_run" edge.
func HasBenchRun() predicate.BenchResult {
	return predicate.BenchResult(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BenchRunTable, BenchRunColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBenchRunWith applies the HasEdge predicate on the "bench_run" edge with a given conditions (other predicates).
func HasBenchRunWith(preds ...predicate.BenchRun) predicate.BenchResult {
	return predicate.BenchResult(func(s *sql.Selector) {
		step := newBenchRunStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasBenchEval applies the HasEdge predicate on the "bench_eval" edge.
func HasBenchEval() predicate.BenchResult {
	return predicate.BenchResult(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BenchEvalTable, BenchEvalColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBenchEvalWith applies the HasEdge predicate on the "bench_eval" edge with a given conditions (other predicates).
func HasBenchEvalWith(preds ...predicate.BenchEval) predicate.BenchResult {
	return predicate.BenchResult(func(s *sql.Selector) {
		step := newBenchEvalStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BenchResult) predicate.BenchResult {
	return predicate.BenchResult(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BenchResult) predicate.BenchResult {
	return predicate.BenchResult(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BenchResult) predicate.BenchResult {
	return predicate.BenchResult(sql.NotPredicates(p))
}
